def solve():
    results = {}

    for m in range(1, 21):
        # Check divisibility constraint
        if (m * (m + 1)) % 6 != 0:
            continue

        S = (m * (m + 1)) // 6
        T = list(range(1, m + 1))
        found = False
        best_XY = None

        # Iterate through all non-empty subsets X of {1, ..., m}
        # using bitmasks 1 to 2^m - 1
        for i in range(1, 1 << m):
            X = []
            sum_X = 0
            for k in range(m):
                if (i >> k) & 1:
                    element = T[k]
                    X.append(element)
                    sum_X += element

            if sum_X != S:
                continue

            # X is a valid candidate. Now find Y subset of T \ X summing to S.

            R = [t for t in T if t not in X]

            # Iterate through all non-empty subsets Y of R
            # R has size |R| <= m <= 20. Iterating over 2^|R| subsets is feasible.
            R_size = len(R)
            for j in range(1, 1 << R_size):
                Y = []
                sum_Y = 0
                for l in range(R_size):
                    if (j >> l) & 1:
                        element = R[l]
                        Y.append(element)
                        sum_Y += element

                if sum_Y == S:
                    # Found a valid pair (X, Y)
                    best_XY = (X, Y)
                    found = True
                    break # Found Y for this X

            if found:
                break # Found a pair for this m

        if found:
            results[m] = best_XY

    return results

results = solve()
